def solve_nqueens_with_constraints():
    n = 13
    fixed = {1: 12, 11: 1}

    solution = [None] * n

    # Place fixed queens
    for row, col in fixed.items():
        solution[row] = col

    def is_safe(solution, row, col):
        for r in range(n):
            if solution[r] is None:
                continue
            if r == row:
                continue
            c = solution[r]
            # Same column
            if c == col:
                return False
            # Same diagonal
            if abs(r - row) == abs(c - col):
                return False
        return True

    def backtrack(row):
        if row == n:
            return True
        if solution[row] is not None:
            # Fixed value, just verify and move on
            if is_safe(solution, row, solution[row]):
                return backtrack(row + 1)
            else:
                return False

        for col in range(n):
            if is_safe(solution, row, col):
                solution[row] = col
                if backtrack(row + 1):
                    return True
                solution[row] = None
        return False

    if backtrack(0):
        return solution
    return None

result = solve_nqueens_with_constraints()
print("Solution:", result)

if result:
    # Verify solution
    n = 13
    valid = True
    for i in range(n):
        for j in range(i+1, n):
            if result[i] == result[j]:
                print(f"CONFLICT: rows {i} and {j} same column {result[i]}")
                valid = False
            if abs(i-j) == abs(result[i]-result[j]):
                print(f"CONFLICT: rows {i} and {j} on same diagonal")
                valid = False
    if valid:
        print("Solution is VALID!")
    print(f"q[1]={result[1]}, q[11]={result[11]}")

    # Print board
    print("\nBoard:")
    for r in range(n):
        row_str = ""
        for c in range(n):
            if result[r] == c:
                row_str += "Q "
            else:
                row_str += ". "
        print(f"Row {r:2d}: {row_str}")
